pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    ERC1271Signer maker;
    MockToken baseAsset;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new ERC1271Signer();
        baseAsset = new MockToken();
    }

    function testFuzz_property(uint256 duration, uint256 premium, uint256 warpTo) public {
        duration = bound(duration, 1, 10_000 days - 1);
        premium = bound(premium, 0, type(uint128).max);
        warpTo = bound(warpTo, 1, 2_000_000_000);
        vm.warp(warpTo);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(baseAsset),
            strike: 0,
            premium: premium,
            duration: duration,
            expiration: warpTo + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory signature = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        uint256 longPositionId = uint256(c.hashOrder(order));

        vm.prank(address(0xB0B));
        c.fillOrder(order, signature, floorAssetTokenIds);

        assertTrue(c.positionExpirations(longPositionId) == warpTo + duration);
    }
}

